def _mean_profile(names, key):
    arrs = [np.asarray(PROFILES[n][key], np.float64) for n in names]
    out = np.zeros(max(len(a) for a in arrs))
    for a in arrs:
        out[: len(a)] += a
    return out / len(arrs)


def _map(depth, src, dst):
    src, dst = np.asarray(src, np.float64), np.asarray(dst, np.float64)
    y = np.interp(depth, src, dst)
    lo, hi = depth < src[0], depth > src[-1]
    y = np.where(lo, dst[0] + (depth - src[0]) * (dst[1] - dst[0]) / (src[1] - src[0]), y)
    return np.where(hi, dst[-1] + (depth - src[-1]) * (dst[-1] - dst[-2]) / (src[-1] - src[-2]), y)


def hagen2016_cell(population: str, target_bounds_um, *, merge: int = 1) -> CableCell:
    """The reduced cell of a Hagen 2016 population (``L23E L23I L4E L4I L5E L5I L6E L6I``) in a target
    column with layer boundaries ``target_bounds_um`` (six increasing depths in um below the pia: pia,
    L1|L2/3, L2/3|L4, L4|L5, L5|L6, white matter). ``merge`` joins that many consecutive 10 um bins
    into one compartment (areas summed, Rall sums averaged).

    Hagen et al. 2016, doi:10.1093/cercor/bhw237.
    """
    if population not in POPULATIONS:
        raise ValueError(f"unknown Hagen 2016 population {population!r}; one of {tuple(POPULATIONS)}")
    tb = np.asarray(target_bounds_um, np.float64)
    if tb.shape != (6,) or not np.all(np.isfinite(tb)) or not np.all(np.diff(tb) > 0):
        raise ValueError("target_bounds_um must be six finite, strictly increasing depths")
    merge = int(merge)
    if merge < 1:
        raise ValueError("merge must be >= 1")
    names = POPULATIONS[population]
    s_len = float(np.mean([PROFILES[n]["soma_length_um"] for n in names]))
    s_area = float(np.mean([np.pi * PROFILES[n]["soma_diam_um"] * PROFILES[n]["soma_length_um"] for n in names]))
    s_diam = s_area / (np.pi * s_len)   # keeps the mean soma area
    li = _LAYER_INDEX[population[:-1]]
    src_soma = 0.5 * (SOURCE_BOUNDS_UM[li] + SOURCE_BOUNDS_UM[li + 1])
    soma = float(_map(np.array(src_soma), SOURCE_BOUNDS_UM, tb))
    half = 0.5 * s_len
    branches = []
    for key, sign in (("up", -1.0), ("down", 1.0)):
        area = _mean_profile(names, key + "_area_um2")
        d32 = _mean_profile(names, key + "_rall_d32")
        n = len(area) // merge * merge
        rest = len(area) - n
        if rest:   # the last, partial group keeps its own bins
            area = np.concatenate([area[:n].reshape(-1, merge).sum(1), [area[n:].sum()]])
            d32 = np.concatenate([d32[:n].reshape(-1, merge).mean(1), [d32[n:].mean()]])
            far = np.concatenate([np.arange(1, n // merge + 1) * merge, [n + rest]]) * BIN_UM
        else:
            area = area.reshape(-1, merge).sum(1)
            d32 = d32.reshape(-1, merge).mean(1)
            far = np.arange(1, n // merge + 1) * merge * BIN_UM
        if not (np.all(area > 0) and np.all(d32 > 0)):
            raise ValueError(f"{population} {key} profile has an empty bin; raise merge")
        edges = _map(src_soma + sign * (half + far), SOURCE_BOUNDS_UM, tb)
        edges = np.concatenate([[soma + sign * half], edges])
        branches.append({"edges_um": edges, "area_um2": area, "diam_um": d32 ** (2.0 / 3.0)})
    return profile_cell(soma, s_diam, s_len, branches)
